#include <Arduino.h>
#include <stdlib.h>

char buffer[24];
uint8_t used = 0;
unsigned long lastByte = 0;

void applyThreshold(long threshold) {
  for (int anode = 1; anode <= 10; ++anode) {
    digitalWrite(anode + 1, anode < threshold ? HIGH : LOW);
  }
}

void finishInput() {
  if (!used) return;
  buffer[used] = '\0';
  char *end;
  long threshold = strtol(buffer, &end, 10);
  if (end != buffer) applyThreshold(threshold);
  used = 0;
}

void setup() {
  for (int pin = 2; pin <= 11; ++pin) {
    pinMode(pin, OUTPUT);
    digitalWrite(pin, LOW);
  }
  Serial.begin(9600);
}

void loop() {
  while (Serial.available() > 0) {
    char c = (char)Serial.read();
    lastByte = millis();
    if (c == '\n' || c == '\r') {
      finishInput();
    } else if (used < sizeof(buffer) - 1) {
      buffer[used++] = c;
    }
  }
  if (used && (unsigned long)(millis() - lastByte) >= 20) {
    finishInput();
  }
}
